{"compatibility":"minor","safety_note_md":"# SafeStan Safety Note

Compatibility: minor.

Protected data: `deaths_observed`.

Generated files: `model_safe.stan`, `data_safe.json`.

Changes: added `N_deaths_observed` and `deaths_observed`, where `deaths_observed` is the deterministic flattening, in the original likelihood order, of `deaths[i, m]` for countries `m = 1..M` and days `i` with `EpidemicStart[m] <= i <= N[m]`; `N_deaths_observed` is its length. For the supplied synthetic data this gives `deaths_observed = [3, 5]`. The looped/sliced deaths likelihood was replaced by one vectorized sampling statement on this protected top-level copy. The elementwise prior loop for parameter `y` was vectorized to the equivalent top-level prior `y ~ exponential(1 / tau)`.
","model_safe_stan":"data {
  int<lower=1> M; // number of countries
  int<lower=1> P; // number of covariates
  int<lower=1> N0; // number of days for which to impute infections
  array[M] int<lower=1> N; // days of observed data for country m. each entry must be <= N2
  int<lower=1> N2; // days of observed data + // of days to forecast
  array[N2, M] int cases; // reported cases
  array[N2, M] int deaths; // reported deaths -- the rows with i > N contain -1 and should be ignored
  matrix[N2, M] f; // h * s
  array[M] matrix[N2, P] X;
  array[M] int EpidemicStart;
  array[M] real pop;
  array[N2] real SI; // fixed pre-calculated SI using emprical data from Neil
  int<lower=1> N_deaths_observed;
  array[N_deaths_observed] int<lower=0> deaths_observed;
}
transformed data {
  vector[N2] SI_rev; // SI in reverse order
  array[M] vector[N2] f_rev; // f in reversed order

  for (i in 1 : N2) {
    SI_rev[i] = SI[N2 - i + 1];
  }

  for (m in 1 : M) {
    for (i in 1 : N2) {
      f_rev[m, i] = f[N2 - i + 1, m];
    }
  }
}
parameters {
  array[M] real<lower=0> mu; // intercept for Rt
  array[P] real<lower=0> alpha_hier; // sudo parameter for the hier term for alpha
  real<lower=0> kappa;
  array[M] real<lower=0> y;
  real<lower=0> phi;
  real<lower=0> tau;
  array[M] real<lower=0> ifr_noise;
}
transformed parameters {
  vector[P] alpha;
  matrix[N2, M] prediction = rep_matrix(0, N2, M);
  matrix[N2, M] E_deaths = rep_matrix(0, N2, M);
  matrix[N2, M] Rt = rep_matrix(0, N2, M);
  matrix[N2, M] Rt_adj = Rt;

  {
    matrix[N2, M] cumm_sum = rep_matrix(0, N2, M);
    for (i in 1 : P) {
      alpha[i] = alpha_hier[i] - (log(1.05) / 6.0);
    }
    for (m in 1 : M) {
      /*
      for (i in 2:N0){
        cumm_sum[i,m] = cumm_sum[i-1,m] + y[m];
      }
      */
      prediction[1 : N0, m] = rep_vector(y[m], N0); // learn the number of cases in the first N0 days
      cumm_sum[2 : N0, m] = cumulative_sum(prediction[2 : N0, m]);

      Rt[ : , m] = mu[m] * exp(-X[m] * alpha);
      Rt_adj[1 : N0, m] = Rt[1 : N0, m];
      for (i in (N0 + 1) : N2) {
        /*
        real convolution=0;
        for(j in 1:(i-1)) {
          convolution += prediction[j, m] * SI[i-j];
        }
        */
        real convolution = dot_product(sub_col(prediction, 1, m, i - 1),
                                       tail(SI_rev, i - 1));

        cumm_sum[i, m] = cumm_sum[i - 1, m] + prediction[i - 1, m];
        Rt_adj[i, m] = ((pop[m] - cumm_sum[i, m]) / pop[m]) * Rt[i, m];
        prediction[i, m] = Rt_adj[i, m] * convolution;
      }

      E_deaths[1, m] = 1e-15 * prediction[1, m];
      for (i in 2 : N2) {
        // for(j in 1:(i-1)){
        //   E_deaths[i,m] += prediction[j,m] * f[i-j,m] * ifr_noise[m];
        // }
        E_deaths[i, m] = ifr_noise[m]
                         * dot_product(sub_col(prediction, 1, m, i - 1),
                                       tail(f_rev[m], i - 1));
      }
    }
  }
}
model {
  tau ~ exponential(0.03);
  y ~ exponential(1 / tau);
  phi ~ normal(0, 5);
  kappa ~ normal(0, 0.5);
  mu ~ normal(3.28, kappa); // citation: https://academic.oup.com/jtm/article/27/2/taaa021/5735319
  alpha_hier ~ gamma(.1667, 1);
  ifr_noise ~ normal(1, 0.1);
  {
    vector[N_deaths_observed] E_deaths_observed;
    int pos = 1;
    for (m in 1 : M) {
      if (EpidemicStart[m] <= N[m]) {
        for (i in EpidemicStart[m] : N[m]) {
          E_deaths_observed[pos] = E_deaths[i, m];
          pos += 1;
        }
      }
    }
    deaths_observed ~ neg_binomial_2(E_deaths_observed, phi);
  }
}
generated quantities {
  matrix[N2, M] prediction0 = rep_matrix(0, N2, M);
  matrix[N2, M] E_deaths0 = rep_matrix(0, N2, M);

  {
    matrix[N2, M] cumm_sum0 = rep_matrix(0, N2, M);
    for (m in 1 : M) {
      for (i in 2 : N0) {
        cumm_sum0[i, m] = cumm_sum0[i - 1, m] + y[m];
      }
      prediction0[1 : N0, m] = rep_vector(y[m], N0);
      for (i in (N0 + 1) : N2) {
        real convolution0 = 0;
        for (j in 1 : (i - 1)) {
          convolution0 += prediction0[j, m] * SI[i - j];
        }
        cumm_sum0[i, m] = cumm_sum0[i - 1, m] + prediction0[i - 1, m];
        prediction0[i, m] = ((pop[m] - cumm_sum0[i, m]) / pop[m]) * mu[m]
                            * convolution0;
      }

      E_deaths0[1, m] = uniform_rng(1e-16, 1e-15);
      for (i in 2 : N2) {
        for (j in 1 : (i - 1)) {
          E_deaths0[i, m] += prediction0[j, m] * f[i - j, m] * ifr_noise[m];
        }
      }
    }
  }
}
